"""Build .trivyignore.yaml from Trivy JSON reports: one entry per CVE, scoped to the exact
package versions (purls) found, with a statement per exception category (issue #58).

    python .github/scripts/trivyignore.py <reports dir> .trivyignore.yaml <YYYY-MM-DD>

The reports are the security workflow's "security-image-reports" artifact from a run
without the ignore file. A finding outside the known categories, or a Debian package
in postgres that has a fix, stops the script: fix it instead of accepting it."""
import collections
import glob
import json
import os
import sys

reports, out, expires = sys.argv[1], sys.argv[2], sys.argv[3]

CATEGORIES = {
    "postgres-os": (
        "postgres:17 (Debian 13): no Debian fix released yet. PostgreSQL is reachable only "
        "from the Compose network and the host's loopback; these are OS libraries and "
        "tools, not the server itself."),
    "postgres-gosu": (
        "postgres:17 gosu, built by upstream with an old Go. gosu only drops privileges once "
        "at container start; it opens no sockets and parses no input. Fixed when the official "
        "image rebuilds gosu."),
    "alloy": (
        "grafana/alloy:v1.20.1-distroless is the newest release. Alloy listens on loopback "
        "and the Compose networks only and pushes outbound to Grafana Cloud. Fixed in an "
        "upstream release."),
    "frontend-build-npm": (
        "Build stage only, never deployed: npm's own bundled dependencies in node:24-alpine "
        "after upgrading to the newest npm 11. They run once in CI on this repository's "
        "lockfile."),
    "frontend-build-esbuild": (
        "Build stage only, never deployed: esbuild binary (Vite 6) built with an old Go. It "
        "bundles this repository's sources; the Go network and TLS code it carries is unused."),
    "backend-build-testcontainers": (
        "Build stage only, never deployed: HttpComponents shaded into Testcontainers 2.0.5's "
        "docker-java transport (newest release). Test scope; talks only to the local Docker "
        "socket."),
}


def category(image, result, vuln):
    path = vuln.get("PkgPath") or result.get("Target", "")
    if image.startswith("postgres"):
        if result.get("Type") == "gobinary":
            return "postgres-gosu"
        if vuln.get("FixedVersion"):
            raise SystemExit(f"postgres OS fix available, upgrade instead: {vuln['VulnerabilityID']}")
        return "postgres-os"
    if image.startswith("grafana_alloy"):
        return "alloy"
    if image == "scan_frontend-build":
        return "frontend-build-esbuild" if "esbuild" in path else "frontend-build-npm"
    if image in ("scan_api-build", "scan_datajob-build") and "docker-java" in path:
        return "backend-build-testcontainers"
    raise SystemExit(f"no exception category for {image}: {vuln['VulnerabilityID']} {path}")


entries = collections.defaultdict(set)
for file in sorted(glob.glob(os.path.join(reports, "*.json"))):
    image = os.path.basename(file)[:-5]
    for result in json.load(open(file, encoding="utf-8")).get("Results", []):
        for vuln in result.get("Vulnerabilities") or []:
            purl = vuln.get("PkgIdentifier", {}).get("PURL")
            if not purl:
                raise SystemExit(f"no purl for {image}: {vuln['VulnerabilityID']}")
            entries[(category(image, result, vuln), vuln["VulnerabilityID"])].add(purl)

lines = [
    "# Accepted Trivy findings (issue #58). The security workflow fails on every other",
    "# medium or higher finding. Each entry matches only the exact package versions listed,",
    "# so an image update re-raises it for review, and expires on the date given.",
    "# Generated by .github/scripts/trivyignore.py; regenerate rather than editing by hand.",
    "vulnerabilities:",
]
current = None
for (cat, vid), purls in sorted(entries.items()):
    if cat != current:
        lines += ["", f"  # --- {cat}"]
        current = cat
    lines.append(f"  - id: {vid}")
    lines.append("    purls:")
    lines += [f'      - "{p}"' for p in sorted(purls)]
    lines.append(f'    statement: "{CATEGORIES[cat]}"')
    lines.append(f"    expired_at: {expires}")

with open(out, "w", encoding="utf-8", newline="\n") as f:
    f.write("\n".join(lines) + "\n")
print(len(entries), "entries written")
